test('rounds 25 units with case size 12 up above 2 cases to 3 cases and 36 units', function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 25, caseSize: 12 }), { cases: 3, shippedUnits: 36 });
});

test('raises 5 units with case size 12 that round under 2 cases to 2 cases and 24 units', function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 5, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

test('keeps an exact multiple of 24 units with case size 12 at 2 cases and 24 units', function () {
  assert.deepEqual(code.roundOrderToCases({ orderUnits: 24, caseSize: 12 }), { cases: 2, shippedUnits: 24 });
});

